const result = $input.first().json;
const statusText = String(result.status || result.state || result.task_status || '').toLowerCase();
const text = [
  result.message,
  result.error,
  result.failure_reason,
  result.reasoning,
  result.response,
  result.detail
].filter(Boolean).join(' ').toLowerCase();
const success = ['completed', 'success', 'succeeded'].includes(statusText) || result.success === true;
const needsInput = !success && [
  'captcha',
  'human verification',
  'verify you are human',
  'otp',
  'one-time',
  '2fa',
  'two-factor',
  'login',
  'sign in',
  'missing',
  'required',
  'authorization',
  'work authorization'
].some((needle) => text.includes(needle));
return [{
  json: {
    status: success ? 'success' : needsInput ? 'needs_input' : 'failed',
    currentStep: success ? 'Application submitted' : needsInput ? 'Manual attention needed' : 'Fallback automation stopped',
    message: result.message || result.failure_reason || (success ? 'Application submitted successfully.' : needsInput ? 'The site needs manual attention before automation can continue.' : 'Skyvern could not complete the application.'),
    blockingQuestion: needsInput ? (result.message || result.failure_reason || 'Please handle the site blocker and try again.') : undefined,
    inputField: needsInput ? 'manual_review' : undefined,
    raw: result
  }
}];
